import { Sala, Atividade, CreateAtividadeDTO, UpdateAtividadeDTO, ApiError } from "./types";

const getBaseUrl = () => {
  return (import.meta.env?.VITE_API_URL) || "http://localhost:3000";
};

const getHeaders = (): HeadersInit => {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
  };
  const selectedUserId = localStorage.getItem("selectedUserId");
  if (selectedUserId) {
    headers["X-Usuario"] = selectedUserId;
  }
  return headers;
};

const request = async <T>(path: string, options: RequestInit = {}): Promise<T> => {
  const url = `${getBaseUrl()}${path}`;
  const headers = { ...getHeaders(), ...options.headers };
  const res = await fetch(url, { ...options, headers });

  if (!res.ok) {
    let errorData: any;
    try {
      errorData = await res.json();
    } catch {
      errorData = { erro: "ERRO_DESCONHECIDO", mensagem: "Erro desconhecido na API" };
    }
    throw new ApiError(
      res.status,
      errorData.erro || "ERRO_DESCONHECIDO",
      errorData.mensagem || "Erro inesperado"
    );
  }

  return res.json() as Promise<T>;
};

export const api = {
  getSalas: async (): Promise<Sala[]> => {
    return request<Sala[]>("/salas");
  },

  getAtividades: async (filters?: { dia?: string; tipo?: "palestra" | "minicurso" }): Promise<Atividade[]> => {
    let query = "";
    if (filters) {
      const params = new URLSearchParams();
      if (filters.dia) params.append("dia", filters.dia);
      if (filters.tipo) params.append("tipo", filters.tipo);
      const queryString = params.toString();
      if (queryString) {
        query = `?${queryString}`;
      }
    }
    return request<Atividade[]>(`/atividades${query}`);
  },

  getAtividade: async (id: string): Promise<Atividade> => {
    return request<Atividade>(`/atividades/${id}`);
  },

  createAtividade: async (data: CreateAtividadeDTO): Promise<Atividade> => {
    return request<Atividade>("/atividades", {
      method: "POST",
      body: JSON.stringify(data),
    });
  },

  updateAtividade: async (id: string, data: UpdateAtividadeDTO): Promise<Atividade> => {
    return request<Atividade>(`/atividades/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    });
  },

  cancelAtividade: async (id: string): Promise<Atividade> => {
    return request<Atividade>(`/atividades/${id}/cancelamento`, {
      method: "POST",
    });
  },
};

import { useState } from "react";
import { User, INITIAL_USERS } from "../users";

export function useSelectedUser() {
  const [selectedUser, setSelectedUser] = useState<User | null>(() => {
    const savedId = localStorage.getItem("selectedUserId");
    if (savedId) {
      const found = INITIAL_USERS.find((u) => u.id === savedId);
      if (found) return found;
    }
    return null;
  });

  const selectUser = (userId: string | null) => {
    if (!userId) {
      localStorage.removeItem("selectedUserId");
      setSelectedUser(null);
    } else {
      const found = INITIAL_USERS.find((u) => u.id === userId);
      if (found) {
        localStorage.setItem("selectedUserId", userId);
        setSelectedUser(found);
      } else {
        localStorage.removeItem("selectedUserId");
        setSelectedUser(null);
      }
    }
  };

  return {
    selectedUser,
    selectUser,
    users: INITIAL_USERS,
  };
}

import React from "react";
import { User } from "../users";

interface UserSelectorProps {
  selectedUser: User | null;
  onSelectUser: (userId: string | null) => void;
  users: User[];
}

export function UserSelector({ selectedUser, onSelectUser, users }: UserSelectorProps) {
  return (
    <div className="user-selector-container">
      <label htmlFor="demo-user-select">Selecione o usuário de demonstração:</label>
      <select
        id="demo-user-select"
        value={selectedUser?.id || ""}
        onChange={(e) => {
          const val = e.target.value;
          onSelectUser(val ? val : null);
        }}
      >
        <option value="">Selecione um usuário</option>
        {users.map((user) => (
          <option key={user.id} value={user.id}>
            {user.nome} ({user.papel})
          </option>
        ))}
      </select>
    </div>
  );
}

